Given a row-wise sorted matrix mat[][] of size n x m, where the number of rows and columns is always odd. Return the median of the matrix.Examples: Input: mat[][] =  [[1 3 5], [2 6 9], [3 6 9]]Output: 5Explanation: Elements in sorted order: 1 2 3 3 5 6 6 9 9. There are total 9 elements, thus the median is the element at index 5 (1-based) i.e. 5.Input: mat[][] = [[1 3 4], [2 5 6], [3 7 9]]Output: 4Explanation: Elements in sorted order: 1 2 3 3 4 5 6 7 9. There are total 9 elements, thus the median is the element at index 5 (1-based) i.e. 4.Try It YourselfTable of Content[Naive Approach] Using Sorting - O(n × m × log(n × m)) Time and O(n × m) Space[Better Approach] Using Priority Queue[Expected Approach] Using Binary Search[Naive Approach] Using Sorting - O(n × m × log(n × m)) Time and O(n × m) SpaceThe idea is to first flatten the 2D matrix into a 1D array by collecting all its elements. Then, the array is sorted to bring all elements into order. Since the total number of elements is odd, the median is the middle element of the sorted array. 
            C++

    #include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int median(vector<vector<int>> &mat) {

    // flatten the matrix into a 1-dimensional array
    vector<int> arr;
    for (int i = 0; i < mat.size(); i++) {
        for (int j = 0; j < mat[0].size(); j++) {
            arr.push_back(mat[i][j]);
        }
    }

    // sort the array
    sort(arr.begin(), arr.end());

    // find the median element
    int mid = arr.size() / 2;
    return arr[mid];
}

int main() {
    vector<vector<int>> matrix = 
                        {{1, 3, 5}, 
                         {2, 6, 9}, 
                         {3, 6, 9}};
    cout << median(matrix) << endl;
    return 0;
}


